s=s.replace("from scipy.optimize import curve_fit\n","""
def bestK(x,y,V=None):
    Ks=np.exp(np.linspace(np.log(0.01),np.log(1e5),20001))
    best=None
    for K in Ks:
        f=x/(K+x); v=V if V is not None else (f@y)/(f@f)
        r=((y-v*f)**2).sum()
        if best is None or r<best[0]: best=(r,v,K)
    for _ in range(3):
        K0=best[2]
        for K in np.linspace(K0*0.999,K0*1.001,2001):
            f=x/(K+x); v=V if V is not None else (f@y)/(f@f)
            r=((y-v*f)**2).sum()
            if r<best[0]: best=(r,v,K)
    return best[1],best[2]
""")
s=s.replace("p,_=curve_fit(lambda s,V,K:V*s/(K+s),x,y,p0=[y.max(),20])","p=bestK(x,y)")
s=s.replace("p,_=curve_fit(lambda s,K:V*s/(K+s),x,y,p0=[50]); res[c]=(V,p[0]); print(c,len(x),V,p)","_,K=bestK(x,y,V); res[c]=(V,K); print(c,len(x),V,K)")
open('fit.py','w').write(s)

